    {!readOnly && <div className="button-wrap">
      {actions.canEdit && <button className="button" type="button" disabled={busy} onClick={() => onAction('edit', item)}>Edit text</button>}
      {actions.canDelete && <button className="button danger" type="button" disabled={busy} onClick={() => onAction('delete', item)}>{actions.deleteScope === 'self' ? 'Remove from my view' : actions.deleteScope === 'unsend' ? 'Unsend message' : 'Delete message'}</button>}
      {actions.canReact && <button className="button" type="button" disabled={busy} onClick={() => onAction('react', item)}>React</button>}
      {actions.canUnreact && <button className="button" type="button" disabled={busy} onClick={() => onAction('unreact', item)}>Remove my reaction</button>}
    </div>}
    {!readOnly && platform === 'imessage' && item.direction === 'outgoing' && !item.isDeleted && <small>iMessage: edit within 15 minutes; unsend within 2 minutes. Refresh to check the remaining window.</small>}
  </>;
